package cl.dynasty.nexusbeacon.platform.classic;
import java.util.Collections;import java.util.HashSet;import java.util.Set;import org.bukkit.Material;import org.bukkit.configuration.ConfigurationSection;import cl.dynasty.nexusbeacon.platform.api.MaterialContext;
public final class ClassicBeamRenderPolicy {interface MaterialLookup{Material at(int x,int y,int z);}private final boolean enabled;private final boolean always;private final int maxLayers;private final Set<Material> powerBlocks;
 public ClassicBeamRenderPolicy(ConfigurationSection config,ClassicMaterialResolver resolver){enabled=config.getBoolean("visual-beam.enabled",true);always="ALWAYS".equalsIgnoreCase(config.getString("visual-beam.render-mode","AUTO"));maxLayers=Math.max(1,config.getInt("beacon.power.max-layers",4));Set<Material> values=new HashSet<Material>();ConfigurationSection power=config.getConfigurationSection("beacon.power");if(power!=null){add(values,power.getConfigurationSection("blocks"),resolver);add(values,power.getConfigurationSection("vanilla-blocks"),resolver);add(values,power.getConfigurationSection("custom-blocks"),resolver);}powerBlocks=Collections.unmodifiableSet(values);}
 ClassicBeamRenderPolicy(boolean enabled,String mode,int layers,Set<Material> blocks){this.enabled=enabled;always="ALWAYS".equalsIgnoreCase(mode);maxLayers=layers;powerBlocks=new HashSet<Material>(blocks);}
 boolean shouldRender(ClassicBeaconRecord record,MaterialLookup lookup){if(!enabled||record==null)return false;if(always)return true;if(lookup==null)return false;ClassicBeaconLocation l=record.getLocation();for(int layer=1;layer<=maxLayers;layer++)for(int x=-layer;x<=layer;x++)for(int z=-layer;z<=layer;z++){Material m=lookup.at(l.getX()+x,l.getY()-layer,l.getZ()+z);if(powerBlocks.contains(m)&&!vanilla(m))return true;}return false;}
 private static void add(Set<Material> out,ConfigurationSection s,ClassicMaterialResolver r){if(s==null)return;for(String name:s.getKeys(false))if(s.getInt(name,0)>0)r.resolveMaterial(name,MaterialContext.BLOCK_MATCH).getMaterial().ifPresent(out::add);}
 private static boolean vanilla(Material m){if(m==null)return false;String n=m.name();return "IRON_BLOCK".equals(n)||"GOLD_BLOCK".equals(n)||"EMERALD_BLOCK".equals(n)||"DIAMOND_BLOCK".equals(n);}}
